#ifndef BB_LEVEL_DATA_H
#define BB_LEVEL_DATA_H

/*
 * Level data in ROM. Generated by tools/map2c from assets/levels/*.map
 * plus the per-round settings in assets/levels/*.txt, so this header is
 * shared between the game and the tool.
 */

#include <stdint.h>

#define LEVEL_W 32
#define LEVEL_H 26
#define LEVEL_CELLS (LEVEL_W * LEVEL_H)
#define LEVEL_MAX_ENEMIES 8
#define LEVEL_TILESETS    8      /* tileset numbers 0..7 (files tileset01..08.png) */

/* One byte per cell: bit 7 = solid, bits 0..2 = airflow direction. */
#define CELL_SOLID    0x80u
#define CELL_AIR_MASK 0x07u

enum { AIR_NONE = 0, AIR_UP = 1, AIR_DOWN = 2, AIR_LEFT = 3, AIR_RIGHT = 4 };

#define ENEMY_TYPE_WALKER  1   /* walks, jumps up to the player, drops off edges */
#define ENEMY_TYPE_BOUNCER 2   /* flies diagonally, ignores platforms */
#define ENEMY_TYPE_THROWER 3   /* walker that stops and throws rocks */
#define ENEMY_TYPE_FLUTTER 4   /* flies freely through platforms, changes direction often */
#define ENEMY_TYPE_HOPPER  5   /* bounces in arcs on a spring, rebounds off walls */
#define ENEMY_TYPE_SPITTER 6   /* fast walker, weak jumper, spits fireballs while running */
#define ENEMY_TYPE_DROPPER 7   /* patrols left/right, drops off edges, shoots straight down */
#define ENEMY_TYPE_COUNT   7
#define LEVEL_ENEMY_FACE_LEFT 0x01u

/* What kind of room a level is. */
enum { LEVEL_NORMAL = 0, LEVEL_BOSS = 1, LEVEL_SECRET = 2 };

/* Special bubbles a round sends in through its opening. */
enum { SPECIAL_NONE = 0, SPECIAL_WATER = 1, SPECIAL_FIRE = 2, SPECIAL_LIGHTNING = 3 };

typedef struct {
    uint8_t x;      /* tile column of the enemy's feet */
    uint8_t y;      /* tile row of the enemy's feet */
    uint8_t type;   /* ENEMY_TYPE_* */
    uint8_t flags;  /* LEVEL_ENEMY_* */
    uint8_t delay;  /* frames before it enters the round */
} LevelEnemy;

typedef struct {
    const uint8_t    *cells;        /* LEVEL_CELLS bytes, row-major */
    const LevelEnemy *enemies;
    uint8_t           enemy_count;
    uint8_t           tileset;      /* 0..LEVEL_TILESETS-1 */
    uint16_t          hurry_frames; /* frames until HURRY UP; 0 = never */
    uint8_t           special;      /* SPECIAL_* */
    uint16_t          special_frames; /* frames between two special bubbles */
    uint8_t           kind;         /* LEVEL_* */
} LevelDef;

extern const LevelDef level_defs[];
extern const uint8_t  level_count;

#endif /* BB_LEVEL_DATA_H */
